/**
 * Post-processes the TypeScript declaration files (.d.ts) for the notehub-js library.
 *
 * The declarations themselves are generated by OpenAPI Generator from the `*.d.ts.mustache`
 * templates in `libTemplate/` (wired in via the `files` block in `config.json`), so their
 * types are derived from the same structured model the generator uses to emit the runtime
 * `.js` — no re-parsing of generated JavaScript. This script only performs the mechanical
 * clean-up the generator can't do itself:
 *
 *   1. Rename model/api declarations from `*.ts` to `*.d.ts`. OpenAPI Generator collapses
 *      the `.d.ts` double extension to `.ts` for Model/API user templates, so the templates
 *      emit `*.ts` and we rename here. (index.d.ts and ApiClient.d.ts use SupportingFiles
 *      templates, which honor the full name, so they need no rename.)
 *   2. Normalize the bare `Object` free-form-object type into an index signature.
 *   3. Drop unused imports (allOf parents flattened into members, error-response models)
 *      and sort the remaining import lines.
 *
 * Run after `generateDocs` (see root package.json `generateTypes` script); Prettier runs
 * afterwards to finalize formatting.
 */

const fs = require("fs");
const path = require("path");

const SRC = path.join(__dirname, "..", "..", "src", "src");

/** Clean up a single generated declaration file's contents. */
function processContents(code) {
  let lines = code.split("\n");

  // Normalize the bare free-form-object type OpenAPI Generator emits as `Object`
  // (additionalProperties responses) into an index signature so callers can read
  // arbitrary keys. `Object` never appears as a bare type otherwise.
  lines = lines.map((line) =>
    line.replace(/\bObject\b/g, "{ [key: string]: any }"),
  );

  // Sort import lines and drop those whose identifier is unused in the file body.
  const importLines = lines.filter((line) => /^import\s/.test(line));
  const body = lines.filter((line) => !/^import\s/.test(line));
  const bodyText = body.join("\n");
  const kept = importLines
    .filter((line) => {
      const m = line.match(/^import\s+(\w+)\s+from\s+/);
      return !m || new RegExp(`\\b${m[1]}\\b`).test(bodyText);
    })
    .sort();

  return (kept.length ? kept.join("\n") + "\n" : "") + bodyText;
}

/** Rename `*.ts` -> `*.d.ts` (skipping already-renamed files) and clean each declaration. */
function processDir(dir) {
  let count = 0;
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith(".ts") || file.endsWith(".d.ts")) continue;
    const src = path.join(dir, file);
    const dest = path.join(dir, file.replace(/\.ts$/, ".d.ts"));
    fs.writeFileSync(dest, processContents(fs.readFileSync(src, "utf8")));
    fs.unlinkSync(src);
    count++;
  }
  return count;
}

/** Clean an already-correctly-named declaration file in place. */
function processFileInPlace(file) {
  if (!fs.existsSync(file)) return 0;
  fs.writeFileSync(file, processContents(fs.readFileSync(file, "utf8")));
  return 1;
}

/** Reflect the `*.ts` -> `*.d.ts` model/api rename in the generator's file manifest. */
function patchManifest() {
  const manifest = path.join(SRC, "..", ".openapi-generator", "FILES");
  if (!fs.existsSync(manifest)) return;
  const patched = fs
    .readFileSync(manifest, "utf8")
    .split("\n")
    .map((line) =>
      /^src\/(model|api)\/.+(?<!\.d)\.ts$/.test(line)
        ? line.replace(/\.ts$/, ".d.ts")
        : line,
    )
    .join("\n");
  fs.writeFileSync(manifest, patched);
}

function main() {
  const models = processDir(path.join(SRC, "model"));
  const apis = processDir(path.join(SRC, "api"));
  processFileInPlace(path.join(SRC, "index.d.ts"));
  processFileInPlace(path.join(SRC, "ApiClient.d.ts"));
  patchManifest();
  console.log(
    `Post-processed .d.ts: ${models} models, ${apis} apis, ApiClient, index.`,
  );
}

main();
